// Package transport provides predefined transport protocol.
package transport

// Protocol indicates the transport protocol.
type Protocol int

// Predefined transport protocols.
const (
	PurePayload Protocol = 0
	TTHeader    Protocol = 2
	Framed      Protocol = 4
	HTTP        Protocol = 8
	GRPC        Protocol = 16
	HESSIAN2    Protocol = 32

	// Composite protocols
	TTHeaderFramed Protocol = 6 // TTHeader | Framed (2 | 4)

	// Streaming protocols (using higher bits to avoid conflicts)
	TTHeaderStreaming Protocol = 64  // Dedicated flag for TTHeader streaming
	GRPCStreaming     Protocol = 128 // Dedicated flag for gRPC streaming
)

// Unknown indicates the protocol is unknown.
const Unknown = "Unknown"

// String prints human readable information.
func (tp Protocol) String() string {
	// Handle exact matches first (including composite constants)
	switch tp {
	case PurePayload:
		return "PurePayload"
	case TTHeader:
		return "TTHeader"
	case Framed:
		return "Framed"
	case HTTP:
		return "HTTP"
	case TTHeaderFramed:
		return "TTHeaderFramed"
	case GRPC:
		return "GRPC"
	case HESSIAN2:
		return "Hessian2"
	case TTHeaderStreaming:
		return "TTHeaderStreaming"
	case GRPCStreaming:
		return "GRPCStreaming"
	}

	// Handle composite values: check all flags in ascending bit order
	var parts []string

	// Check each flag in ascending order of bit value
	flags := []struct {
		value Protocol
		name  string
	}{
		{TTHeader, "TTHeader"},
		{Framed, "Framed"},
		{HTTP, "HTTP"},
		{GRPC, "GRPC"},
		{HESSIAN2, "Hessian2"},
		{TTHeaderStreaming, "TTHeaderStreaming"},
		{GRPCStreaming, "GRPCStreaming"},
	}

	for _, flag := range flags {
		if tp&flag.value != 0 {
			parts = append(parts, flag.name)
		}
	}

	if len(parts) > 0 {
		result := parts[0]
		for i := 1; i < len(parts); i++ {
			result += "|" + parts[i]
		}
		return result
	}

	return Unknown
}
