package client

// UnaryOption is a type alias for Option, used to indicate options that apply to unary RPC calls
type UnaryOption = Option

// StreamOption is a type alias for Option, used to indicate options that apply to streaming RPC calls
type StreamOption = Option

// TTHeaderStreamingOption is a type alias for Option, used to indicate options specific to TTHeader streaming
type TTHeaderStreamingOption = Option

// ToUnaryOption converts a generic Option to a UnaryOption
func ToUnaryOption(opt Option) UnaryOption {
	return UnaryOption(opt)
}

// ToStreamOption converts a generic Option to a StreamOption
func ToStreamOption(opt Option) StreamOption {
	return StreamOption(opt)
}

// ToTTHeaderStreamingOption converts a generic Option to a TTHeaderStreamingOption
func ToTTHeaderStreamingOption(opt Option) TTHeaderStreamingOption {
	return TTHeaderStreamingOption(opt)
}

// UnaryOptions creates a slice of UnaryOption from a slice of Options
func UnaryOptions(opts ...Option) []UnaryOption {
	result := make([]UnaryOption, len(opts))
	for i, opt := range opts {
		result[i] = UnaryOption(opt)
	}
	return result
}

// StreamOptions creates a slice of StreamOption from a slice of Options
func StreamOptions(opts ...Option) []StreamOption {
	result := make([]StreamOption, len(opts))
	for i, opt := range opts {
		result[i] = StreamOption(opt)
	}
	return result
}

// TTHeaderStreamingOptions creates a slice of TTHeaderStreamingOption from a slice of Options
func TTHeaderStreamingOptions(opts ...Option) []TTHeaderStreamingOption {
	result := make([]TTHeaderStreamingOption, len(opts))
	for i, opt := range opts {
		result[i] = TTHeaderStreamingOption(opt)
	}
	return result
}
