package client

import (
	"time"

	"github.com/cloudwego/kitex/pkg/endpoint"
)

// WithUnaryOptions sets options specifically for unary RPC calls.
// This allows fine-grained control over unary call behavior without affecting streaming calls.
func WithUnaryOptions(opts ...UnaryOption) Option {
	return Option{F: func(o *Options, di *dIOptions) {
		for _, opt := range opts {
			opt.F(&o.UnaryOptions)
		}
	}}
}

// WithUnaryRPCTimeout sets the RPC timeout specifically for unary calls.
// This timeout applies to the entire unary RPC call from start to finish.
func WithUnaryRPCTimeout(d time.Duration) UnaryOption {
	return UnaryOption{F: func(o *UnaryOptions) {
		o.Configs.RPCTimeout = d
	}}
}

// WithUnaryConnectTimeout sets the connection timeout specifically for unary calls.
func WithUnaryConnectTimeout(d time.Duration) UnaryOption {
	return UnaryOption{F: func(o *UnaryOptions) {
		o.Configs.ConnectTimeout = d
	}}
}

// WithUnaryMiddleware adds a middleware specifically for unary RPC calls.
// The middleware will be applied to all unary calls made by this client.
func WithUnaryMiddleware(mw endpoint.Middleware) UnaryOption {
	return UnaryOption{F: func(o *UnaryOptions) {
		o.Middlewares = append(o.Middlewares, mw)
	}}
}

