func WithStreamSendTimeout(d time.Duration) StreamOption {
	return StreamOption{F: func(o *StreamOptions) {
		o.SendTimeout = d
	}}
}

// WithStreamMiddleware adds a middleware that applies to both send and receive operations.
// The middleware will be applied to all streaming calls made by this client.
func WithStreamMiddleware(mw endpoint.Middleware) StreamOption {
